contains

    ! Function to calculate the sum of squares from 1 to n
    integer function sum_of_squares(n)
        implicit none
        integer :: n, i
        integer :: sum

        sum = 0
        do i = 1, n
            sum = sum + i * i  ! Add the square of i to sum
        end do

