   Estimate diffusion coefficient from MSD(t)
   Fit ⟨r²⟩ = slope * t → D = slope / 4  (in 2D)
   ========================================================== */
double estimate_diffusion(double *t, double *msd_avg, int nsteps)
{
    int i;
    double num = 0.0, den = 0.0, slope;

    for (i = 1; i < nsteps; i++) { /* skip t=0 */
        num += t[i] * msd_avg[i];
        den += t[i] * t[i];
    }

    slope = num / den;
    return slope / 4.0;
}

