    while (flag_iterate) {
        pass += 1;
        flag_iterate = false;

        // Bubble sorting pass
        for (int i = 0; i < N - 1; i++) {
            if (arr[i + 1] < arr[i]) {
                flag_iterate = true;
                hold = arr[i];
                arr[i] = arr[i + 1];
                arr[i + 1] = hold;
