int count_numbers_in_file(FILE *input_file) {
  int count = 0;
  int temp;

  // Count the number of integers in the file
  while (fscanf(input_file, "%d", &temp) != EOF) {
    count++;
  }

  // Reset the file pointer to the beginning for the next read
  rewind(input_file);

  return count;
}

