    fclose(output_file);
    return 1;
  }

  // Allocate memory for the array
  int *arr = malloc(N * sizeof(int));
  if (arr == NULL) {
    fprintf(output_file, "Error: Memory allocation failed.\n");
    fclose(input_file);
    fclose(output_file);
    return 1;
  }

  // Read the elements from the input file
  for (int i = 0; i < N; i++) {
    fscanf(input_file, "%d", &arr[i]);
  }

  // Perform bubble sort and write to output file
  bubble_sorting(N, arr, output_file);

  // Free the allocated memory
  free(arr);

  // Close the files
  fclose(input_file);
  fclose(output_file);

  printf("Sorting complete. Results written to %s\n", argv[2]);

  return 0;
}

In this exercise, you are required to write a program that dynamically allocates memory for two square matrices, A and B, of size N \times N , and computes their sum in a third matrix C.

Here a to do list that can help:

Ask the user to input the size of the matrix  N  (which must be greater than 0).

Dynamically allocate memory for three matrices A, B, and C, each of size  N \times N.

Populate the matrices A and B with some values (e.g., fill matrix A with values  i \times N + j  and matrix B with values  i \times N + j + 100. where i and j are the row and column indices, respectively).

Create a function sum_matrices that takes the two input matrices A and B and computes their sum into matrix C.

Print out the resulting matrix C after computing the sum.

Ensure that you free the allocated memory before exiting the program to avoid memory leaks.

C code#include <stdio.h>
#include <stdlib.h>

// Function to sum two NxN matrices A and B, storing the result in C
void sum_matrices(float **A, float **B, float **C, int N){
  for(int i=0; i<N; i++){
    for(int j=0; j<N; j++){
      *(*(C+i)+j) = *(*(A+i)+j) + *(*(B+i)+j);
    }
  }
}

int main(int argc, char* argv[]){

  int N;
  float **A, **B, **C;

  // Prompt user for input
  printf("A and B are NxN matrices. Insert the value of N:\n");
  scanf("%d", &N);
  if(N <= 0){
    printf("N must be greater than 0.\n");
    return 1;
  }

  // Allocate memory for matrices A, B, and C
  A = (float **)malloc(N * sizeof(float *));
  B = (float **)malloc(N * sizeof(float *));
  C = (float **)malloc(N * sizeof(float *));
  if (A == NULL || B == NULL || C == NULL) {
    printf("Memory allocation failed.\n");
    return 1;
  }

  for(int i=0; i<N; i++){
    A[i] = (float *)malloc(N * sizeof(float));
    B[i] = (float *)malloc(N * sizeof(float));
    C[i] = (float *)malloc(N * sizeof(float));
    if (A[i] == NULL || B[i] == NULL || C[i] == NULL) {
      printf("Memory allocation failed.\n");
      return 1;
    }
  }

  // Populate matrices A and B
  for(int i=0; i<N; i++){
    for(int j=0; j<N; j++){
      A[i][j] = i * N + j;
      B[i][j] = i * N + j + 100;
    }
  }

  // Compute sum: C = A + B
  sum_matrices(A, B, C, N);

  // Print matrix C
  printf("Matrix C = A + B:\n");
  for(int i=0; i<N; i++){
    for(int j=0; j<N; j++){
      printf("C[%d][%d] = %f\n", i, j, C[i][j]);
    }
  }

  // Free allocated memory
  for(int i=0; i<N; i++){
    free(A[i]);
    free(B[i]);
    free(C[i]);
  }
  free(A);
  free(B);
  free(C);

  return 0;
}

