contains

  ! Define the function to integrate here
  real(8) function f(x,lab)
    real(8), intent(in) :: x
    integer,intent(in)  :: lab
    select case(lab)
    case(1)
      f = exp(-cos(x)*cos(x))                 ! Example: Integrate exp(-x^2) over [-1, 1]
    case(2)
