    case(6)
      f = exp(-x*x)
    end select
  end function

  subroutine generate_weights_abscissae(w,x)
    implicit none
    real(8), intent(inout)               :: w
    real(8), dimension(:), intent(inout) :: x
    real(8), parameter                   :: pi = 3.141592653589793d0
    integer :: N
    N = size(x)
