// Kernel to use the device function
__global__ void compute_cubes(const double *input, double *output, int n) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < n) {
        output[idx] = cube(input[idx]); // Calling the device function
    }
}

