Consider the following code parallelised with CUDA C.#include <stdio.h>
#include <stdlib.h>
#include <cuda.h>
#include <time.h>

//#define N 1024  // Matrix size

// Kernel for matrix multiplication
__global__ void matrix_multiply_kernel(double *A, double *B, double *C, int size) {
    int row = blockIdx.y * blockDim.y + threadIdx.y; // Row index
    int col = blockIdx.x * blockDim.x + threadIdx.x; // Column index

    if (row < size && col < size) {
        double sum = 0.0;
        for (int k = 0; k < size; k++) {
            sum += A[row * size + k] * B[k * size + col];
        }
        C[row * size + col] = sum;
    }
}

int main(int argc, char* argv[]) {
    double *A, *B, *C;           // Host pointers
    double *d_A, *d_B, *d_C;     // Device pointers
    clock_t start, end;
    double cpu_time_used;

    cudaDeviceProp prop;
    cudaGetDeviceProperties(&prop, 0);

    if (argc < 4) {
      printf("Usage: %s <N> <blockDim.x> <blockDim.y>:\n", argv[0]);
      printf("<N> in the number of rows and columns (NxN matrix)\n");
      printf("<blockDim.x> is the number of threads in the block (x direction)\n");
      printf("<blockDim.y> is the number of threads in the block (y direction)\n");
      return 1;
    }

    int N = atoi(argv[1]);
    int block_dim_x = atoi(argv[2]);
    int block_dim_y = atoi(argv[3]);

    if(block_dim_x*block_dim_y>prop.maxThreadsPerBlock){
      printf("Max threads per block: %d\n", prop.maxThreadsPerBlock);
      printf("You chose %d x %d = %d threads\n", block_dim_x, block_dim_y, block_dim_x*block_dim_y);
      return 1;
    }

    size_t matrix_size = N * N * sizeof(double);

    // Allocate memory on the host
    A = (double*) malloc(matrix_size);
    B = (double*) malloc(matrix_size);
    C = (double*) malloc(matrix_size);

    // Initialize matrices (example initialization)
    for (int i = 0; i < N * N; i++) {
        A[i] = 0.01*i;
        B[i] = 0.025*i;
    }

    // Allocate memory on the device
    cudaMalloc((void**)&d_A, matrix_size);
    cudaMalloc((void**)&d_B, matrix_size);
    cudaMalloc((void**)&d_C, matrix_size);

    // Copy matrices A and B from host to device
    cudaMemcpy(d_A, A, matrix_size, cudaMemcpyHostToDevice);
    cudaMemcpy(d_B, B, matrix_size, cudaMemcpyHostToDevice);

    // Define grid and block dimensions
    dim3 blockDim(block_dim_x, block_dim_y);
    dim3 gridDim((N + blockDim.x - 1) / blockDim.x, (N + blockDim.y - 1) / blockDim.y);

    // Start timing
    start = clock();

    // Launch kernel
    matrix_multiply_kernel<<<gridDim, blockDim>>>(d_A, d_B, d_C, N);

    // Wait for the GPU to finish
    cudaError_t err = cudaDeviceSynchronize();
    if (err != cudaSuccess) {
      printf("Kernel execution failed: %s\n", cudaGetErrorString(err));
    }

    // Stop timing
    end = clock();
    cpu_time_used = ((double) (end - start)) / CLOCKS_PER_SEC;

    // Copy result matrix C from device to host
    cudaMemcpy(C, d_C, matrix_size, cudaMemcpyDeviceToHost);

    //printf("Matrix multiplication completed in %.2f ms\n", cpu_time_used * 1000);
    printf("%d %d %d %.6f\n", N, block_dim_x, block_dim_y, cpu_time_used);

    // Free memory on device
    cudaFree(d_A);
    cudaFree(d_B);
    cudaFree(d_C);

    // Free memory on host
    free(A);
    free(B);
    free(C);

    return 0;
}

In this code, we vary the size N and the number of threads per block, both along x and y (block_dim_x and block_dim_y). Note that the times are taken right before the call to the kernel matrix_multiply_kernel and after the call to cudaDeviceSynchronize().
This last call is crucial, because kernel launches are asynchronous, meaning that the host (CPU) does not wait for the kernel execution on the device (GPU) to finish before continuing to the next line of code. If you measure time immediately after launching a kernel without waiting for its completion, the measured time will not accurately reflect the kernel’s execution duration.

Note

Unix-like systems support multitasking by letting many processes make progress over time.
On a single CPU core, only one process executes instructions at any instant, so the kernel uses time-sharing: it runs a process for a short time slice, p
reempts it (typically via a timer interrupt), then schedules another. On multiple cores, different processes (or threads) can run truly in parallel,
but the programming model is the same: you write code assuming multiple independent execution contexts, and the kernel decides when and where they run.
In Unix, fork() is the classic system call to create a new process: it produces a child process that begins as a near-copy of the parent
(same program image and inherited open file descriptors) and returns twice—0 in the child, and the child’s PID in the parent—after which the two processes
continue independently. From that point, the parent can keep doing useful work while the child performs a long task, and the two can coordinate using
primitives such as waitpid() (to reap the child and obtain its exit status) and IPC mechanisms like pipe() to exchange data.

This is how one can use the fork() syscall to start a child process:// fork_wait_min.c — minimal fork()/waitpid() skeleton
// Build:  cc -O2 -Wall -Wextra -pedantic fork_wait_min.c -o fork_wait_min
// Run:    ./fork_wait_min

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>

int main(void) {
    pid_t pid = fork();
    if (pid < 0)  { perror("fork"); exit(1); }

    if (pid == 0) {
        // Child process
        printf("child:  pid=%ld, ppid=%ld\n", (long)getpid(), (long)getppid());
        exit(42);                  // choose an exit code to demonstrate status handling
    }

    // Parent process
    printf("parent: pid=%ld, spawned child pid=%ld\n", (long)getpid(), (long)pid);

    int status = 0;

    if (waitpid(pid, &status, 0) < 0) { perror("waitpid"); exit(1); }

    if (WIFEXITED(status)) {
        printf("parent: child exited normally, code=%d\n", WEXITSTATUS(status));
    } else if (WIFSIGNALED(status)) {
        printf("parent: child killed by signal %d\n", WTERMSIG(status));
    } else {
        printf("parent: child ended in an unusual way (status=0x%x)\n", status);
    }

    return 0;
}

The code first spawns a new process with fork():    pid_t pid = fork();

If something goes wrong (e.g., exceeding the number of allowed processes or memory limits) the kernel sets the value of the variable errrno
to that of the specific error, and -1 is stored in pid. In this case we can use perror() to print the associated message, e.g.,fork: Resource temporarily unavailable

If everything went well, there will be two processes running (either alternating in time sharing or in parallel on multiple cores/CPUs) from the moment  fork() was called:

the old, parent process, with information about the process ID of the child stored in pid

the new, child process, with zero stored in pid.

The child process can access its own pid by calling getpid(), and the pid of its parent by calling getppid()    if (pid == 0) {
        // Child process
        printf("child:  pid=%ld, ppid=%ld\n", (long)getpid(), (long)getppid());
        exit(42);                  // choose an exit code to demonstrate status handling
    }

